-- Фундаментальные показатели бумаг MOEX (point-in-time, INV-1, INV-9).
-- Для каждого тикера хранятся исторические срезы отчётности с датой публикации available_at,
-- чтобы открытые сессии арены никогда не заглядывали в будущую отчётность (available_at <= cursorDate).
CREATE TABLE marketdata.security_fundamentals (
    ticker               TEXT           NOT NULL,
    report_date          DATE           NOT NULL,
    available_at         DATE           NOT NULL,
    period_type          TEXT           NOT NULL CHECK (period_type IN ('FY', 'Q1', 'Q2', 'Q3', 'Q4', 'TTM')),
    currency             TEXT           NOT NULL DEFAULT 'RUB',
    -- Оценка (Valuation)
    market_cap_rub       NUMERIC(20, 2),
    pe_ratio             NUMERIC(12, 4),
    pb_ratio             NUMERIC(12, 4),
    ps_ratio             NUMERIC(12, 4),
    ev_ebitda            NUMERIC(12, 4),
    -- Рентабельность и рост (Profitability & Growth, % x100)
    roe                  NUMERIC(10, 4),
    roa                  NUMERIC(10, 4),
    gross_margin         NUMERIC(10, 4),
    operating_margin     NUMERIC(10, 4),
    net_margin           NUMERIC(10, 4),
    revenue_growth_yoy   NUMERIC(10, 4),
    eps_growth_yoy       NUMERIC(10, 4),
    -- Финансовая устойчивость, на акцию и дивиденды
    debt_to_equity       NUMERIC(12, 4),
    current_ratio        NUMERIC(12, 4),
    eps                  NUMERIC(14, 4),
    book_value_per_share NUMERIC(14, 4),
    dividend_yield       NUMERIC(10, 4),
    payout_ratio         NUMERIC(10, 4),
    free_float           NUMERIC(10, 4),
    beta                 NUMERIC(10, 4),
    PRIMARY KEY (ticker, report_date, period_type),
    CONSTRAINT chk_security_fundamentals_available_after_report CHECK (available_at >= report_date)
);

CREATE INDEX idx_security_fundamentals_ticker_available
    ON marketdata.security_fundamentals (ticker, available_at DESC, report_date DESC);

